public class NodeUtil_isValidQualifiedName_TriageGen0Test {

    @Test
    public void testIsValidQualifiedName_ValidSinglePart() {
        assertTrue(NodeUtil.isValidQualifiedName("foo"));
    }

    @Test
    public void testIsValidQualifiedName_ValidMultipleParts() {
        assertTrue(NodeUtil.isValidQualifiedName("foo.bar.baz"));
    }

    @Test
    public void testIsValidQualifiedName_StartsWithDot() {
        assertFalse(NodeUtil.isValidQualifiedName(".foo"));
    }

    @Test
    public void testIsValidQualifiedName_EndsWithDot() {
        assertFalse(NodeUtil.isValidQualifiedName("foo."));
    }

    @Test
    public void testIsValidQualifiedName_EmptyString() {
        // Depending on isValidSimpleName implementation, 
        // an empty string split might result in an empty array or a part containing ""
        // Given the logic, if it doesn't start/end with dot, it proceeds to split.
        // If name is "", startsWith/endsWith are false. split returns [""]
        // If isValidSimpleName("") is false, this returns false.
        assertFalse(NodeUtil.isValidQualifiedName(""));
    }

    @Test
    public void testIsValidQualifiedName_InvalidPart() {
        // Assuming isValidSimpleName returns false for names containing invalid characters like numbers at start or special chars
        // This test ensures the loop logic and the return false branch are covered
        assertFalse(NodeUtil.isValidQualifiedName("foo..bar")); // results in an empty part ""
    }

    @Test
    public void testIsValidQualifiedName_InvalidSimpleName() {
        // Testing a case where one part is invalid (e.g., starting with a digit if that's what isValidSimpleName enforces)
        // Since I don't have the source for isValidSimpleName, I will test the structure that triggers the loop return
        assertFalse(NodeUtil.isValidQualifiedName("foo.1bar")); 
    }
}
